create type public.app_role as enum ('admin', 'proctor', 'subject_teacher');
create type public.approval_state as enum ('pending', 'approved', 'rejected');
create type public.assessment_kind as enum ('midsem', 'internal');
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text not null, email text not null unique, role public.app_role not null default 'subject_teacher', approval_status public.approval_state not null default 'pending', created_at timestamptz not null default now());
create table public.academic_terms (id uuid primary key default gen_random_uuid(), year text not null, semester text not null, active boolean not null default false, unique(year, semester));
create table public.classes (id uuid primary key default gen_random_uuid(), academic_term_id uuid not null references public.academic_terms on delete cascade, branch text not null, batch text not null, year text not null, section text not null, unique(academic_term_id, branch, batch, year, section));
create table public.subjects (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null);
create table public.class_subjects (id uuid primary key default gen_random_uuid(), class_id uuid not null references public.classes on delete cascade, subject_id uuid not null references public.subjects on delete cascade, unique(class_id, subject_id));
create table public.teacher_assignments (id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.profiles on delete cascade, class_id uuid not null references public.classes on delete cascade, subject_id uuid references public.subjects on delete cascade, assignment_role public.app_role not null check (assignment_role in ('proctor','subject_teacher')), check ((assignment_role = 'proctor' and subject_id is null) or (assignment_role = 'subject_teacher' and subject_id is not null)), unique(teacher_id,class_id,subject_id,assignment_role));
create table public.students (id uuid primary key default gen_random_uuid(), enrollment_number text not null unique, full_name text not null, class_id uuid not null references public.classes on delete cascade);
create table public.attendance_uploads (id uuid primary key default gen_random_uuid(), class_id uuid not null references public.classes on delete cascade, subject_id uuid not null references public.subjects on delete cascade, month date not null, uploaded_by uuid not null references public.profiles, processed_at timestamptz not null default now());
create table public.attendance_records (id uuid primary key default gen_random_uuid(), attendance_upload_id uuid not null references public.attendance_uploads on delete cascade, student_id uuid not null references public.students on delete cascade, lectures_held numeric not null check(lectures_held >= 0), lectures_attended numeric not null check(lectures_attended >= 0 and lectures_attended <= lectures_held), percentage numeric generated always as (case when lectures_held = 0 then 0 else round(lectures_attended / lectures_held * 100, 2) end) stored, unique(attendance_upload_id,student_id));
create table public.assessment_uploads (id uuid primary key default gen_random_uuid(), class_id uuid not null references public.classes on delete cascade, subject_id uuid not null references public.subjects on delete cascade, assessment_type public.assessment_kind not null, uploaded_by uuid not null references public.profiles, processed_at timestamptz not null default now());
create table public.assessment_records (id uuid primary key default gen_random_uuid(), assessment_upload_id uuid not null references public.assessment_uploads on delete cascade, student_id uuid not null references public.students on delete cascade, component_name text not null, marks numeric not null check(marks >= 0), maximum_marks numeric not null check(maximum_marks > 0 and marks <= maximum_marks), unique(assessment_upload_id,student_id,component_name));
create table public.internal_weightages (id uuid primary key default gen_random_uuid(), academic_term_id uuid not null unique references public.academic_terms on delete cascade, assignment_weight numeric not null check(assignment_weight >= 0), presentation_weight numeric not null check(presentation_weight >= 0), attendance_weight numeric not null check(attendance_weight >= 0), midsem_1_weight numeric not null check(midsem_1_weight >= 0), midsem_2_weight numeric not null check(midsem_2_weight >= 0), check(assignment_weight + presentation_weight + attendance_weight + midsem_1_weight + midsem_2_weight = 100));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from profiles where id = auth.uid() and role = 'admin' and approval_status = 'approved') $$;
create or replace function public.can_access_class(target_class uuid) returns boolean language sql stable security definer set search_path = public as $$ select public.is_admin() or exists(select 1 from teacher_assignments where teacher_id=auth.uid() and class_id=target_class) $$;
create or replace function public.can_access_subject(target_class uuid, target_subject uuid) returns boolean language sql stable security definer set search_path = public as $$ select public.is_admin() or exists(select 1 from teacher_assignments where teacher_id=auth.uid() and class_id=target_class and (assignment_role='proctor' or subject_id=target_subject)) $$;
alter table public.profiles enable row level security; alter table public.academic_terms enable row level security; alter table public.classes enable row level security; alter table public.subjects enable row level security; alter table public.class_subjects enable row level security; alter table public.teacher_assignments enable row level security; alter table public.students enable row level security; alter table public.attendance_uploads enable row level security; alter table public.attendance_records enable row level security; alter table public.assessment_uploads enable row level security; alter table public.assessment_records enable row level security; alter table public.internal_weightages enable row level security;
create policy "profiles read own or admin" on public.profiles for select using (id=auth.uid() or public.is_admin()); create policy "admins manage profiles" on public.profiles for all using (public.is_admin()) with check (public.is_admin());
create policy "terms visible to approved users" on public.academic_terms for select using ((select approval_status from profiles where id=auth.uid())='approved'); create policy "admins manage terms" on public.academic_terms for all using(public.is_admin()) with check(public.is_admin());
create policy "classes authorized" on public.classes for select using(public.can_access_class(id)); create policy "admins manage classes" on public.classes for all using(public.is_admin()) with check(public.is_admin());
create policy "subjects authorized" on public.subjects for select using(exists(select 1 from class_subjects cs where cs.subject_id=id and public.can_access_subject(cs.class_id,id))); create policy "admins manage subjects" on public.subjects for all using(public.is_admin()) with check(public.is_admin());
create policy "class subjects authorized" on public.class_subjects for select using(public.can_access_subject(class_id,subject_id)); create policy "admins manage class subjects" on public.class_subjects for all using(public.is_admin()) with check(public.is_admin());
create policy "assignments own or admin" on public.teacher_assignments for select using(teacher_id=auth.uid() or public.is_admin()); create policy "admins manage assignments" on public.teacher_assignments for all using(public.is_admin()) with check(public.is_admin());
create policy "students authorized" on public.students for select using(public.can_access_class(class_id)); create policy "admins manage students" on public.students for all using(public.is_admin()) with check(public.is_admin());
create policy "attendance uploads authorized" on public.attendance_uploads for select using(public.can_access_subject(class_id,subject_id)); create policy "teachers create attendance" on public.attendance_uploads for insert with check(uploaded_by=auth.uid() and public.can_access_subject(class_id,subject_id)); create policy "attendance records authorized" on public.attendance_records for select using(exists(select 1 from attendance_uploads u where u.id=attendance_upload_id and public.can_access_subject(u.class_id,u.subject_id))); create policy "teachers create attendance records" on public.attendance_records for insert with check(exists(select 1 from attendance_uploads u where u.id=attendance_upload_id and u.uploaded_by=auth.uid() and public.can_access_subject(u.class_id,u.subject_id)));
create policy "assessment uploads authorized" on public.assessment_uploads for select using(public.can_access_subject(class_id,subject_id)); create policy "teachers create assessments" on public.assessment_uploads for insert with check(uploaded_by=auth.uid() and public.can_access_subject(class_id,subject_id)); create policy "assessment records authorized" on public.assessment_records for select using(exists(select 1 from assessment_uploads u where u.id=assessment_upload_id and public.can_access_subject(u.class_id,u.subject_id))); create policy "teachers create assessment records" on public.assessment_records for insert with check(exists(select 1 from assessment_uploads u where u.id=assessment_upload_id and u.uploaded_by=auth.uid() and public.can_access_subject(u.class_id,u.subject_id)));
create policy "weightages authorized" on public.internal_weightages for select using((select approval_status from profiles where id=auth.uid())='approved'); create policy "admins manage weightages" on public.internal_weightages for all using(public.is_admin()) with check(public.is_admin());
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Teacher'),new.email); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.create_profile();
